import type { StructureCode } from "@/types";

/**
 * Local marketing images (public/marketing, generated by scripts/marketing/*): real renders of
 * our 3D models with sample artwork, and studio-style sample tiles. No hotlinked photos.
 */
export const RENDER_ID: Record<StructureCode, string> = {
  FEFCO_0427: "fefco-0427",
  FEFCO_0201: "fefco-0201",
  ECMA_RTE: "ecma-rte",
  ECMA_STE: "ecma-ste",
  PIZZA: "pizza",
  SLEEVE: "sleeve",
  FEFCO_0320: "fefco-0320",
  ECMA_CLB: "ecma-clb",
  ECMA_SLB: "ecma-slb",
  FEFCO_0422: "fefco-0422",
  GABLE_BOX: "gable-box",
  PAPER_TUBE: "paper-tube",
  RIGID_BOX: "rigid-box",
  ROLL_LABEL: "bottle",
  PRINTED_POUCH: "jar",
  PRINTED_TUBE: "pump",
};

export function renderSrc(code: StructureCode): string {
  return `/marketing/renders/${RENDER_ID[code]}.webp`;
}

export const VESSEL_RENDERS = ["jar", "bottle", "dropper", "pump", "can"] as const;
export type VesselRender = (typeof VESSEL_RENDERS)[number];
export function vesselSrc(id: VesselRender): string {
  return `/marketing/renders/${id}.webp`;
}

